-- SOMENTE fixture sintética para PostgreSQL descartável. NÃO representa baseline de produção.
CREATE TABLE estudante(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nome VARCHAR(255), email VARCHAR(255) UNIQUE, senha VARCHAR(255), data_nascimento DATE);
CREATE TABLE mentora(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nome VARCHAR(255), email VARCHAR(255) UNIQUE, senha VARCHAR(255), data_nascimento DATE, aprovada BOOLEAN);
CREATE TABLE perfil(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, biografia VARCHAR(255), num_seguidores INTEGER DEFAULT 0, num_seguindo INTEGER DEFAULT 0, num_publicacoes INTEGER DEFAULT 0, usuario VARCHAR(255), pfp VARCHAR(255), background VARCHAR(255), id_estudante INTEGER REFERENCES estudante(id), id_mentora INTEGER REFERENCES mentora(id));
CREATE TABLE mentoria(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, titulo VARCHAR(255), descricao VARCHAR(255), progresso INTEGER, id_mentora INTEGER REFERENCES mentora(id));
INSERT INTO mentoria(titulo,descricao,progresso) VALUES('Mentoria anterior sintética','Preservar este registro',0);
CREATE TABLE recuperacao_senha(id VARCHAR(40) PRIMARY KEY, perfil VARCHAR(10) NOT NULL, conta_id INTEGER NOT NULL, token_hash VARCHAR(64) NOT NULL UNIQUE, criado_em TIMESTAMPTZ NOT NULL, expira_em TIMESTAMPTZ NOT NULL, versao BIGINT);
CREATE TABLE onboarding_respostas(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, estudante_id BIGINT UNIQUE NOT NULL, nivel_experiencia VARCHAR(255) NOT NULL, areas_interesse TEXT NOT NULL, objetivos TEXT NOT NULL, principal_dificuldade VARCHAR(255) NOT NULL, formato_aprendizado VARCHAR(255) NOT NULL, data_conclusao TIMESTAMP NOT NULL);
